import { MakeLogicType, actions, afterMount, kea, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'

import { SourceConfig } from '~/queries/schema/schema-general'

export type AvailableSourcesErrorType = 'forbidden' | 'unknown'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface availableSourcesLogicValues {
    availableSources: Record<string, SourceConfig> | null
    availableSourcesError: AvailableSourcesErrorType | null
    availableSourcesLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface availableSourcesLogicActions {
    load: () => any
    loadFailed: (errorType: AvailableSourcesErrorType) => {
        errorType: AvailableSourcesErrorType
    }
    loadFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSuccess: (
        availableSources: Record<string, SourceConfig> | null,
        payload?: any
    ) => {
        availableSources: Record<string, SourceConfig> | null
        payload?: any
    }
}

export type availableSourcesLogicType = MakeLogicType<availableSourcesLogicValues, availableSourcesLogicActions>

export const availableSourcesLogic = kea<availableSourcesLogicType>([
    path(['products', 'dataWarehouse', 'availableSourcesLogic']),
    actions({
        loadFailed: (errorType: AvailableSourcesErrorType) => ({ errorType }),
    }),
    loaders(({ actions }) => ({
        availableSources: [
            null as Record<string, SourceConfig> | null,
            {
                load: async () => {
                    try {
                        return await api.externalDataSources.wizard()
                    } catch (e: any) {
                        // Handled locally rather than rethrown: a 5xx here shouldn't also fire the
                        // global kea-loaders error toast on top of the banner this renders below.
                        actions.loadFailed(e?.status === 403 ? 'forbidden' : 'unknown')
                        return null
                    }
                },
            },
        ],
    })),
    reducers({
        availableSourcesError: [
            null as AvailableSourcesErrorType | null,
            {
                load: () => null,
                loadFailed: (_, { errorType }) => errorType,
            },
        ],
    }),
    afterMount(({ actions }) => {
        actions.load()
    }),
])
